const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const clamp = (n,min,max) => Math.min(max,Math.max(min,n));
const avg = a => a.length ? a.reduce((s,v)=>s+v,0)/a.length : 0;
const sum = a => a.reduce((s,v)=>s+v,0);
const round = (n,d=1) => Number.isFinite(n) ? +n.toFixed(d) : 0;
const escapeHTML = s => String(s ?? '').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function getActiveProfileRecord(){try{const id=localStorage.getItem('atlasiq_active_profile');const profiles=JSON.parse(localStorage.getItem('atlasiq_profiles')||'[]');return profiles.find(p=>p.id===id)||null}catch{return null}}
function currentUniversity(){return getActiveProfileRecord()?.university||'Purdue University'}
function scopedStorageKey(k){if(['atlasiq_theme','atlasiq_profiles','atlasiq_active_profile','atlasiq_guest_mode'].includes(k))return k;const id=localStorage.getItem('atlasiq_active_profile')||'guest';return `atlasiq_profile_${id}_${k.replace(/^atlasiq_/, '')}`}
const storage = {get:(k,f)=>{try{return JSON.parse(localStorage.getItem(scopedStorageKey(k)))??f}catch{return f}},set:(k,v)=>{try{localStorage.setItem(scopedStorageKey(k),JSON.stringify(v))}catch{}},remove:(k)=>{try{localStorage.removeItem(scopedStorageKey(k))}catch{}},key:scopedStorageKey};
let toastTimer;
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2200)}
function copyText(text){navigator.clipboard?.writeText(text).then(()=>toast('Copied to clipboard')).catch(()=>toast('Copy failed'))}
function downloadFile(name, content, type='application/json'){const blob=new Blob([content],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function formatNumber(n){if(!Number.isFinite(n)) return '—';if(Math.abs(n)>=1e6)return (n/1e6).toFixed(1)+'M';if(Math.abs(n)>=1e3)return (n/1e3).toFixed(1)+'K';return Math.abs(n)%1===0?String(n):n.toFixed(2)}

