$('#themeBtn').addEventListener('click',()=>{root.classList.toggle('light');storage.set('atlasiq_theme',root.classList.contains('light')?'light':'dark');drawAllCanvases();});

const revealObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add('visible')}),{threshold:.12});
$$('.reveal').forEach(el=>revealObserver.observe(el));

const counters=$$('[data-counter]');
const counterObs=new IntersectionObserver(entries=>entries.forEach(e=>{if(!e.isIntersecting)return;const el=e.target,target=+el.dataset.counter,start=performance.now();const tick=t=>{const p=Math.min(1,(t-start)/1100);el.textContent=Math.round(target*(1-Math.pow(1-p,3)));if(p<1)requestAnimationFrame(tick)};requestAnimationFrame(tick);counterObs.unobserve(el)}));
counters.forEach(e=>counterObs.observe(e));

const tilt=$('.tilt-card');
if(tilt){tilt.addEventListener('pointermove',e=>{const r=tilt.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;tilt.style.transform=`rotateY(${x*7}deg) rotateX(${-y*7}deg)`});tilt.addEventListener('pointerleave',()=>tilt.style.transform='');}

// particles
const particleCanvas=$('#particleCanvas'),pctx=particleCanvas.getContext('2d');
let particles=[];
function resizeParticles(){const dpr=Math.min(2,devicePixelRatio||1);particleCanvas.width=innerWidth*dpr;particleCanvas.height=innerHeight*dpr;particleCanvas.style.width=innerWidth+'px';particleCanvas.style.height=innerHeight+'px';pctx.setTransform(dpr,0,0,dpr,0,0);particles=Array.from({length:Math.min(90,Math.floor(innerWidth/16))},()=>({x:Math.random()*innerWidth,y:Math.random()*innerHeight,vx:(Math.random()-.5)*.18,vy:(Math.random()-.5)*.18,r:Math.random()*1.5+.4}))}
function animateParticles(){pctx.clearRect(0,0,innerWidth,innerHeight);const light=root.classList.contains('light');for(const p of particles){p.x+=p.vx;p.y+=p.vy;if(p.x<0||p.x>innerWidth)p.vx*=-1;if(p.y<0||p.y>innerHeight)p.vy*=-1;pctx.fillStyle=light?'rgba(40,50,75,.28)':'rgba(245,207,98,.55)';pctx.beginPath();pctx.arc(p.x,p.y,p.r,0,Math.PI*2);pctx.fill()}for(let i=0;i<particles.length;i++)for(let j=i+1;j<particles.length;j++){const a=particles[i],b=particles[j],d=Math.hypot(a.x-b.x,a.y-b.y);if(d<105){pctx.strokeStyle=light?`rgba(40,50,75,${.06*(1-d/105)})`:`rgba(245,207,98,${.11*(1-d/105)})`;pctx.beginPath();pctx.moveTo(a.x,a.y);pctx.lineTo(b.x,b.y);pctx.stroke()}}requestAnimationFrame(animateParticles)}
resizeParticles();animateParticles();addEventListener('resize',resizeParticles);

const commandItems=[
  ['Command Center','#campus','Campus dashboard'],['Semester Simulator','#campus','Model your workload'],['Ripple Engine','#campus','Trace decision consequences'],['Career Intelligence','#campus','Analyze internship readiness'],['Campus Navigator','#campus','Evaluate class transitions'],['Data Studio','#studio','Upload and profile a CSV'],['AutoML Arena','#studio','Compare local models'],['Decision Simulator','#studio','Run what-if analysis'],['AtlasIQ Analyst','#studio','Ask questions about data'],['ProofGraph','#proofgraph','Inspect skill evidence'],['Founder','#about','Meet Niveditha']
];
const palette=$('#commandPalette'),commandInput=$('#commandInput'),commandResults=$('#commandResults');
function renderCommands(q=''){const filtered=commandItems.filter(x=>x.join(' ').toLowerCase().includes(q.toLowerCase()));commandResults.innerHTML=filtered.map((x,i)=>`<button class="command-result ${i===0?'active':''}" data-command="${escapeHTML(x[0])}"><span>${escapeHTML(x[0])}</span><small>${escapeHTML(x[2])}</small></button>`).join('');$$('[data-command]',commandResults).forEach(b=>b.onclick=()=>runCommand(b.dataset.command))}
function openPalette(){palette.classList.add('open');palette.setAttribute('aria-hidden','false');renderCommands();setTimeout(()=>commandInput.focus(),20)}
function closePalette(){palette.classList.remove('open');palette.setAttribute('aria-hidden','true')}
function runCommand(name){const item=commandItems.find(x=>x[0]===name);if(!item)return;closePalette();document.querySelector(item[1]).scrollIntoView();if(name==='Semester Simulator')activateCampus('semester');if(name==='Ripple Engine')activateCampus('ripple');if(name==='Career Intelligence')activateCampus('career');if(name==='Campus Navigator')activateCampus('navigator');if(name==='AutoML Arena')activateStudio('automl');if(name==='Decision Simulator')activateStudio('simulate');if(name==='AtlasIQ Analyst')activateStudio('explain')}
$('#commandBtn').onclick=openPalette;commandInput.oninput=e=>renderCommands(e.target.value);palette.querySelector('.modal-backdrop').onclick=closePalette;addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openPalette()}if(e.key==='Escape'){closePalette();closeMethodModal()}});

// draggable dashboard cards
let dragged=null;$$('.draggable').forEach(card=>{card.addEventListener('dragstart',()=>{dragged=card;card.style.opacity=.45});card.addEventListener('dragend',()=>{card.style.opacity='';dragged=null});card.addEventListener('dragover',e=>e.preventDefault());card.addEventListener('drop',e=>{e.preventDefault();if(!dragged||dragged===card)return;const parent=card.parentElement;const children=[...parent.children];children.indexOf(dragged)<children.indexOf(card)?parent.insertBefore(dragged,card.nextSibling):parent.insertBefore(dragged,card);toast('Dashboard rearranged')})});

// ---------- Canvas helpers ----------
function setupCanvas(canvas){const rect=canvas.getBoundingClientRect();if(!rect.width)return null;const dpr=Math.min(2,devicePixelRatio||1),w=Math.round(rect.width*dpr),h=Math.round((canvas.getAttribute('height')/canvas.getAttribute('width'))*rect.width*dpr);if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h}const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);return {ctx,w:rect.width,h:h/dpr}}
function paletteColors(){return root.classList.contains('light')?{text:'#172033',muted:'#667085',line:'rgba(20,30,50,.12)',gold:'#b98717',cyan:'#1689a4',green:'#16875a',red:'#d33e59',purple:'#7254c9',panel:'#fff'}:{text:'#f5f7fb',muted:'#9ca6bc',line:'rgba(255,255,255,.10)',gold:'#f5cf62',cyan:'#66e5ff',green:'#67e8a3',red:'#ff7d8d',purple:'#ad8cff',panel:'#11172a'}}
function drawAxes(ctx,w,h,pad,c){ctx.strokeStyle=c.line;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(pad,h-pad);ctx.lineTo(w-pad,h-pad);ctx.moveTo(pad,pad);ctx.lineTo(pad,h-pad);ctx.stroke()}
function drawLineChart(canvas,values,{labels=[],color='gold',fill=true,min=null,max=null,highlight=-1}={}){const s=setupCanvas(canvas);if(!s||!values.length)return;const {ctx,w,h}=s,c=paletteColors(),pad=38;ctx.clearRect(0,0,w,h);const lo=min??Math.min(...values),hi=max??Math.max(...values),range=hi-lo||1;drawAxes(ctx,w,h,pad,c);ctx.font='11px sans-serif';ctx.fillStyle=c.muted;ctx.textAlign='right';for(let i=0;i<4;i++){const val=lo+range*(i/3),y=h-pad-(i/3)*(h-pad*2);ctx.fillText(round(val),pad-8,y+4);ctx.strokeStyle=c.line;ctx.beginPath();ctx.moveTo(pad,y);ctx.lineTo(w-pad,y);ctx.stroke()}const pts=values.map((v,i)=>({x:pad+(i/(Math.max(1,values.length-1)))*(w-pad*2),y:h-pad-((v-lo)/range)*(h-pad*2)}));if(fill){const grad=ctx.createLinearGradient(0,pad,0,h-pad);grad.addColorStop(0,c[color]+'55');grad.addColorStop(1,c[color]+'00');ctx.fillStyle=grad;ctx.beginPath();ctx.moveTo(pts[0].x,h-pad);pts.forEach(p=>ctx.lineTo(p.x,p.y));ctx.lineTo(pts.at(-1).x,h-pad);ctx.closePath();ctx.fill()}ctx.strokeStyle=c[color];ctx.lineWidth=2.2;ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.stroke();pts.forEach((p,i)=>{ctx.fillStyle=i===highlight?c.red:c[color];ctx.beginPath();ctx.arc(p.x,p.y,i===highlight?5:2.5,0,Math.PI*2);ctx.fill();if(labels[i]&&(i%Math.ceil(values.length/7)===0||i===values.length-1)){ctx.fillStyle=c.muted;ctx.textAlign='center';ctx.fillText(labels[i],p.x,h-pad+18)}})}
function drawBarChart(canvas,labels,values,{color='gold',horizontal=false}={}){const s=setupCanvas(canvas);if(!s||!values.length)return;const {ctx,w,h}=s,c=paletteColors(),pad=44;ctx.clearRect(0,0,w,h);const max=Math.max(...values.map(Math.abs),1);ctx.font='10px sans-serif';if(horizontal){const bh=(h-pad*2)/values.length*.62;values.forEach((v,i)=>{const y=pad+i*(h-pad*2)/values.length;ctx.fillStyle=c.line;ctx.fillRect(130,y,w-pad-135,bh);ctx.fillStyle=c[color];ctx.fillRect(130,y,(w-pad-135)*Math.abs(v)/max,bh);ctx.fillStyle=c.muted;ctx.textAlign='right';ctx.fillText(String(labels[i]).slice(0,18),122,y+bh*.72);ctx.textAlign='left';ctx.fillText(round(v,2),135+(w-pad-135)*Math.abs(v)/max,y+bh*.72)})}else{drawAxes(ctx,w,h,pad,c);const bw=(w-pad*2)/values.length*.68;values.forEach((v,i)=>{const x=pad+i*(w-pad*2)/values.length+(w-pad*2)/values.length*.16,bh=(h-pad*2)*Math.abs(v)/max;ctx.fillStyle=c[color];ctx.fillRect(x,h-pad-bh,bw,bh);ctx.save();ctx.translate(x+bw/2,h-pad+14);ctx.rotate(-.35);ctx.fillStyle=c.muted;ctx.textAlign='right';ctx.fillText(String(labels[i]).slice(0,12),0,0);ctx.restore()})}}
function drawScatter(canvas,xs,ys,{xLabel='',yLabel='',line=false}={}){const s=setupCanvas(canvas);if(!s||!xs.length)return;const {ctx,w,h}=s,c=paletteColors(),pad=48;ctx.clearRect(0,0,w,h);const xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys),xr=xmax-xmin||1,yr=ymax-ymin||1;drawAxes(ctx,w,h,pad,c);ctx.fillStyle=c.muted;ctx.font='10px sans-serif';ctx.textAlign='center';ctx.fillText(xLabel,w/2,h-7);ctx.save();ctx.translate(12,h/2);ctx.rotate(-Math.PI/2);ctx.fillText(yLabel,0,0);ctx.restore();const pts=xs.map((x,i)=>({x:pad+(x-xmin)/xr*(w-pad*2),y:h-pad-(ys[i]-ymin)/yr*(h-pad*2)}));if(line){ctx.strokeStyle=c.gold;ctx.lineWidth=1.5;ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.stroke()}ctx.fillStyle=c.cyan;pts.forEach(p=>{ctx.globalAlpha=.72;ctx.beginPath();ctx.arc(p.x,p.y,3.1,0,Math.PI*2);ctx.fill()});ctx.globalAlpha=1}
