function haversine(a,b){const R=3958.8,rad=x=>x*Math.PI/180,dlat=rad(b.x-a.x),dlon=rad(b.y-a.y),q=Math.sin(dlat/2)**2+Math.cos(rad(a.x))*Math.cos(rad(b.x))*Math.sin(dlon/2)**2;return 2*R*Math.asin(Math.sqrt(q))}
let routeState={from:$('#fromBuilding').value,to:$('#toBuilding').value,condition:'clear',minutes:15};
function calculateRoute(){routeState={from:$('#fromBuilding').value,to:$('#toBuilding').value,condition:$('#weatherCondition').value,minutes:+$('#transitionMinutes').value};const a=buildings[routeState.from],b=buildings[routeState.to],miles=haversine(a,b)*1.17,base=miles/3*60+2,mult={clear:1,rain:1.16,snow:1.38,crowded:1.22}[routeState.condition],walk=base*mult,buffer=routeState.minutes-walk,risk=buffer>=5?'Low':buffer>=1.5?'Moderate':'High';const score=clamp(Math.round(100-(walk/routeState.minutes)*28-(risk==='High'?28:risk==='Moderate'?12:0)),20,98);$('#routeResult').innerHTML=`<h4>${risk} transition risk · ${round(walk,1)} min estimated</h4><p>${round(miles,2)} miles from ${buildings[routeState.from].short} to ${buildings[routeState.to].short}. You have ${round(buffer,1)} minutes of modeled buffer under ${routeState.condition} conditions. ${risk==='High'?'Leave the prior class immediately or identify a backup route.':risk==='Moderate'?'The route is feasible, but delays could erase the buffer.':'The transition has a healthy resilience margin.'}</p>`;$('#metricRoute').textContent=score;$('#mapsLink').href=`https://www.google.com/maps/dir/?api=1&origin=${encodeURIComponent(routeState.from+', '+currentUniversity())}&destination=${encodeURIComponent(routeState.to+', '+currentUniversity())}&travelmode=walking`;drawCampusMap()}
function drawCampusMap(){const canvas=$('#campusMap'),s=setupCanvas(canvas);if(!s)return;const {ctx,w,h}=s,c=paletteColors(),xs=buildingNames.map(n=>buildings[n].y),ys=buildingNames.map(n=>buildings[n].x),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys),pad=45;ctx.clearRect(0,0,w,h);ctx.fillStyle=root.classList.contains('light')?'#eef1f7':'#0b1020';ctx.fillRect(0,0,w,h);for(let i=0;i<12;i++){ctx.strokeStyle=c.line;ctx.beginPath();ctx.moveTo(0,i*h/12);ctx.lineTo(w,i*h/12);ctx.stroke()}for(let i=0;i<16;i++){ctx.beginPath();ctx.moveTo(i*w/16,0);ctx.lineTo(i*w/16,h);ctx.stroke()}const pos=n=>({x:pad+(buildings[n].y-xmin)/(xmax-xmin)*(w-pad*2),y:h-pad-(buildings[n].x-ymin)/(ymax-ymin)*(h-pad*2)});buildingNames.forEach(n=>{const p=pos(n),active=n===routeState.from||n===routeState.to;ctx.fillStyle=active?c.gold:c.cyan;ctx.beginPath();ctx.arc(p.x,p.y,active?7:4,0,Math.PI*2);ctx.fill();ctx.fillStyle=c.text;ctx.font='10px sans-serif';ctx.fillText(buildings[n].short,p.x+8,p.y-7)});const a=pos(routeState.from),b=pos(routeState.to);ctx.strokeStyle=c.gold;ctx.lineWidth=3;ctx.setLineDash([8,7]);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.quadraticCurveTo((a.x+b.x)/2+25,(a.y+b.y)/2-35,b.x,b.y);ctx.stroke();ctx.setLineDash([])}
