const dataState={name:'',domain:'education',rows:[],profile:null,model:null,chart:{},simulation:null};
function seeded(seed=42){let s=seed>>>0;return()=>((s=(s*1664525+1013904223)>>>0)/4294967296)}
function gaussian(rng){let u=0,v=0;while(!u)u=rng();while(!v)v=rng();return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v)}
function isoDate(start,i){const d=new Date(start);d.setDate(d.getDate()+i);return d.toISOString().slice(0,10)}
function sampleData(domain,n=96){const r=seeded({healthcare:11,finance:22,sports:33,climate:44,education:55}[domain]||77),rows=[];
  for(let i=0;i<n;i++){
    if(domain==='healthcare'){const age=Math.round(20+r()*65),bmi=round(18+r()*18+gaussian(r)*1.8,1),bp=Math.round(95+age*.35+bmi*.7+gaussian(r)*8),adherence=clamp(round(55+r()*45-gaussian(r)*4,1),20,100),prior=Math.max(0,Math.round(r()*4-1)),risk=clamp(round(age*.32+bmi*.7+bp*.16+prior*8-adherence*.28+gaussian(r)*5,1),2,98);rows.push({patient_id:`P${String(i+1).padStart(3,'0')}`,age,bmi,blood_pressure:bp,prior_readmissions:prior,medication_adherence:adherence,risk_score:risk,high_risk:risk>58?'Yes':'No'})}
    if(domain==='finance'){const t=i,season=Math.sin(i/8)*9,revenue=round(180+1.25*t+season+gaussian(r)*9,2),marketing=round(31+Math.sin(i/6)*5+r()*7,2),retention=round(clamp(82-Math.max(0,i-62)*.38+gaussian(r)*2.2,48,94),2),conversion=round(clamp(4.2+marketing*.035+retention*.025+gaussian(r)*.35,2,10),2),profit=round(revenue*.42-marketing*1.65+(retention-70)*.8+gaussian(r)*5,2);rows.push({date:isoDate('2026-01-01',i),region:['North','South','East','West'][i%4],revenue,marketing_spend:marketing,retention_rate:retention,conversion_rate:conversion,profit})}
    if(domain==='sports'){const mins=round(22+r()*17,1),points=round(mins*.58+gaussian(r)*5,1),assists=round(Math.max(0,mins*.15+gaussian(r)*2),1),rebounds=round(Math.max(0,mins*.2+gaussian(r)*2.5),1),eff=round(points+assists*1.5+rebounds*1.2-(r()*5),1),momentum=round(50+Math.sin(i/5)*20+gaussian(r)*8,1),win=eff+momentum*.25>38?'Win':'Loss';rows.push({game:i+1,team:['Gold','Black','White','Gray'][i%4],minutes:mins,points,assists,rebounds,efficiency:eff,momentum,game_result:win})}
    if(domain==='climate'){const season=Math.sin(i/15),temp=round(58+season*24+gaussian(r)*4,1),humidity=round(clamp(65-season*12+gaussian(r)*7,25,98),1),co2=round(418+i*.08+gaussian(r)*1.2,2),rain=round(Math.max(0,humidity*.11-temp*.035+gaussian(r)*2.2),2),heat_index=round(temp+Math.max(0,humidity-60)*.08,1);rows.push({date:isoDate('2026-01-01',i),temperature:temp,humidity,co2_ppm:co2,rainfall_mm:rain,heat_index})}
    if(domain==='education'){const attendance=round(65+r()*35,1),study=round(r()*15,1),prior=round(55+r()*42,1),assign=round(clamp(58+attendance*.34+study*1.3+gaussian(r)*8,20,100),1),stress=round(clamp(82-study*1.8-attendance*.25+gaussian(r)*9,5,100),1),finalGrade=round(clamp(prior*.35+attendance*.18+study*1.25+assign*.28-stress*.06+gaussian(r)*4,35,100),1);rows.push({student_id:`S${String(i+1).padStart(3,'0')}`,attendance_rate:attendance,study_hours:study,prior_grade:prior,assignment_completion:assign,stress_index:stress,final_grade:finalGrade,support_needed:finalGrade<70?'Yes':'No'})}
  }
  // Insert a few realistic quality issues for profiling.
  if(rows.length>20){const keys=Object.keys(rows[0]);rows[7][keys[2]]='';rows[18][keys[3]]='';if(domain!=='sports')rows[31][keys.at(-2)]=null;}
  return rows;
}
function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i],next=text[i+1];if(ch==='"'){if(quoted&&next==='"'){cell+='"';i++}else quoted=!quoted}else if(ch===','&&!quoted){row.push(cell.trim());cell=''}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&next==='\n')i++;row.push(cell.trim());if(row.some(v=>v!==''))rows.push(row);row=[];cell=''}else cell+=ch}if(cell.length||row.length){row.push(cell.trim());rows.push(row)}if(rows.length<2)throw new Error('CSV needs a header and at least one data row.');const headers=rows[0].map((h,i)=>h||`column_${i+1}`);return rows.slice(1).map(r=>Object.fromEntries(headers.map((h,i)=>[h,r[i]??''])))}
function toNum(v){if(v===null||v===undefined||v==='')return null;const n=Number(String(v).replace(/[$,%]/g,''));return Number.isFinite(n)?n:null}
function pearson(a,b){const pairs=a.map((v,i)=>[v,b[i]]).filter(([x,y])=>Number.isFinite(x)&&Number.isFinite(y));if(pairs.length<3)return 0;const ax=pairs.map(x=>x[0]),bx=pairs.map(x=>x[1]),am=avg(ax),bm=avg(bx),num=sum(pairs.map(([x,y])=>(x-am)*(y-bm))),den=Math.sqrt(sum(ax.map(x=>(x-am)**2))*sum(bx.map(x=>(x-bm)**2)));return den?num/den:0}
function quantile(sorted,q){if(!sorted.length)return 0;const pos=(sorted.length-1)*q,base=Math.floor(pos),rest=pos-base;return sorted[base+1]!==undefined?sorted[base]+rest*(sorted[base+1]-sorted[base]):sorted[base]}
function profileRows(rows){const columns=Object.keys(rows[0]||{}),profiles={};let totalMissing=0,totalOutliers=0;for(const col of columns){const raw=rows.map(r=>r[col]),missing=raw.filter(v=>v===null||v===undefined||String(v).trim()==='').length,nums=raw.map(toNum),validNums=nums.filter(Number.isFinite),numeric=validNums.length>=Math.max(3,(raw.length-missing)*.75);let p={name:col,type:numeric?'numeric':(/date|time/i.test(col)&&raw.filter(v=>!isNaN(Date.parse(v))).length>raw.length*.7?'date':'categorical'),missing,unique:new Set(raw.filter(v=>v!==''&&v!=null).map(String)).size};if(numeric){const sorted=[...validNums].sort((a,b)=>a-b),q1=quantile(sorted,.25),q3=quantile(sorted,.75),iqr=q3-q1,lo=q1-1.5*iqr,hi=q3+1.5*iqr,outliers=validNums.filter(v=>v<lo||v>hi).length;p={...p,mean:avg(validNums),min:Math.min(...validNums),max:Math.max(...validNums),median:quantile(sorted,.5),std:Math.sqrt(avg(validNums.map(v=>(v-avg(validNums))**2))),outliers,values:nums};totalOutliers+=outliers}profiles[col]=p;totalMissing+=missing}
  const numeric=columns.filter(c=>profiles[c].type==='numeric'),correlations=[];for(let i=0;i<numeric.length;i++)for(let j=i+1;j<numeric.length;j++){correlations.push({a:numeric[i],b:numeric[j],r:pearson(profiles[numeric[i]].values,profiles[numeric[j]].values)})}correlations.sort((a,b)=>Math.abs(b.r)-Math.abs(a.r));const missingPct=100*totalMissing/(Math.max(1,rows.length*columns.length)),quality=clamp(Math.round(100-missingPct*1.25-Math.min(20,totalOutliers/Math.max(1,rows.length)*12)-Math.max(0,columns.length-18)*.3),30,100);return{columns,profiles,numeric,correlations,missingPct,totalOutliers,quality,rows:rows.length}}
function domainTitle(d){return({healthcare:'Healthcare Risk Sample',finance:'Financial Performance Sample',sports:'Sports Performance Sample',climate:'Climate Trends Sample',education:'Student Outcomes Sample'})[d]||'Uploaded Dataset'}
function loadDomain(domain){dataState.domain=domain;dataState.name=domainTitle(domain);dataState.rows=sampleData(domain);setData(dataState.rows,dataState.name);$$('[data-domain]').forEach(b=>b.classList.toggle('active',b.dataset.domain===domain));toast(`${domainTitle(domain)} loaded`)}
function setData(rows,name='Uploaded Dataset'){if(!rows.length)throw new Error('No rows found.');dataState.rows=rows.slice(0,5000);dataState.name=name;dataState.profile=profileRows(dataState.rows);dataState.model=null;$('#uploadZone').classList.add('hidden');$('#dataWorkspace').classList.remove('hidden');renderProfile();populateColumnControls();activateStudio('data');}
function renderProfile(){const p=dataState.profile;$('#datasetName').textContent=dataState.name;$('#datasetMeta').textContent=`${p.rows.toLocaleString()} rows · ${p.columns.length} columns · analyzed locally`;$('#qualityScore').textContent=p.quality;$('#missingPercent').textContent=round(p.missingPct,1);$('#outlierCount').textContent=p.totalOutliers;const top=p.correlations[0];$('#topCorrelation').textContent=top?Math.abs(top.r).toFixed(2):'N/A';$('#topCorrelationLabel').textContent=top?`${top.a} ↔ ${top.b}`:'No numeric pair';const head=$('#dataPreview thead'),body=$('#dataPreview tbody'),cols=p.columns.slice(0,9);head.innerHTML='<tr>'+cols.map(c=>`<th>${escapeHTML(c)}</th>`).join('')+'</tr>';body.innerHTML=dataState.rows.slice(0,12).map(r=>'<tr>'+cols.map(c=>`<td>${escapeHTML(r[c]??'')}</td>`).join('')+'</tr>').join('');$('#columnList').innerHTML=p.columns.map(c=>{const x=p.profiles[c];return`<div class="column-item"><div><b>${escapeHTML(c)}</b><span>${x.type}</span></div><small>${x.unique} unique · ${x.missing} missing${x.type==='numeric'?` · μ ${round(x.mean,2)}`:''}</small></div>`}).join('');$('#aiSummaryText').textContent=generateSummary();renderPreprocessing();}
function generateSummary(){const p=dataState.profile,top=p.correlations[0],numeric=p.numeric;let text=`AtlasIQ profiled ${p.rows} records across ${p.columns.length} variables. Data quality is ${p.quality}/100 with ${round(p.missingPct,1)}% missing cells and ${p.totalOutliers} IQR-based outlier flags.`;if(top)text+=` The strongest numeric relationship is ${top.a} versus ${top.b} (r=${round(top.r,2)}), which is ${Math.abs(top.r)>.7?'strong':Math.abs(top.r)>.4?'moderate':'weak-to-moderate'}.`;if(dataState.domain==='finance'&&p.profiles.retention_rate)text+=` Retention averages ${round(p.profiles.retention_rate.mean,1)}%, and later records should be inspected for deterioration before treating the revenue trend as sustainable.`;if(dataState.domain==='healthcare')text+=` Risk outputs are educational estimates and must not be interpreted as diagnosis or clinical advice.`;if(dataState.domain==='education'&&p.profiles.final_grade)text+=` Final grades average ${round(p.profiles.final_grade.mean,1)}, with attendance, study time, prior performance, and assignment completion available as candidate drivers.`;if(!numeric.length)text+=' The dataset is primarily categorical, so frequency analysis and classification are more appropriate than numeric forecasting.';return text}
function populateColumnControls(){const p=dataState.profile;const all=p.columns,numeric=p.numeric;const options=arr=>arr.map(c=>`<option value="${escapeHTML(c)}">${escapeHTML(c)}</option>`).join('');$('#xColumn').innerHTML=options(all);$('#yColumn').innerHTML=options(numeric.length?numeric:all);$('#targetColumn').innerHTML=options(all);$('#simTarget').innerHTML=options(numeric);$('#simFeature').innerHTML=options(numeric);const likely={healthcare:'risk_score',finance:'profit',sports:'efficiency',climate:'rainfall_mm',education:'final_grade'}[dataState.domain];if(all.includes(likely)){['#yColumn','#targetColumn','#simTarget'].forEach(s=>$(s).value=likely)}const feature=numeric.find(c=>c!==likely);if(feature){$('#xColumn').value=feature;$('#simFeature').value=feature}dataState.chart={x:$('#xColumn').value,y:$('#yColumn').value,type:'scatter'};renderProfileChatReset()}
