$('#browseBtn').onclick=e=>{e.stopPropagation();csvInput.click()};uploadZone.onclick=e=>{if(e.target.closest('button'))return;csvInput.click()};uploadZone.onkeydown=e=>{if(e.key==='Enter'||e.key===' ')csvInput.click()};['dragenter','dragover'].forEach(ev=>uploadZone.addEventListener(ev,e=>{e.preventDefault();uploadZone.classList.add('dragging')}));['dragleave','drop'].forEach(ev=>uploadZone.addEventListener(ev,e=>{e.preventDefault();uploadZone.classList.remove('dragging')}));uploadZone.addEventListener('drop',e=>{const f=e.dataTransfer.files[0];if(f)readCSVFile(f)});csvInput.onchange=e=>{const f=e.target.files[0];if(f)readCSVFile(f)};
function readCSVFile(file){if(file.size>8_000_000)return toast('Please use a CSV under 8 MB for this browser demo');const reader=new FileReader();reader.onload=()=>{try{const rows=parseCSV(reader.result);dataState.domain='custom';setData(rows,file.name)}catch(err){toast(err.message)}};reader.readAsText(file)}
$('#loadDemoBtn').onclick=()=>loadDomain('education');$('#replaceData').onclick=()=>{$('#dataWorkspace').classList.add('hidden');uploadZone.classList.remove('hidden');csvInput.value=''};$$('[data-domain]').forEach(b=>b.onclick=()=>loadDomain(b.dataset.domain));

// ---------- Visualizations ----------
function cleanPairs(xc,yc){return dataState.rows.map(r=>[toNum(r[xc]),toNum(r[yc])]).filter(([x,y])=>Number.isFinite(x)&&Number.isFinite(y))}
function categoryAggregate(xc,yc){const map=new Map;for(const r of dataState.rows){const k=String(r[xc]??'Missing'),v=toNum(r[yc]);if(Number.isFinite(v)){const a=map.get(k)||[];a.push(v);map.set(k,a)}}return [...map.entries()].slice(0,20).map(([k,v])=>[k,avg(v)])}
function renderMainChart(){if(!dataState.profile)return;const x=$('#xColumn').value,y=$('#yColumn').value,type=$('#chartType').value,canvas=$('#mainChart');dataState.chart={x,y,type};$('#mainChartTitle').textContent=`${y} by ${x}`;const xp=dataState.profile.profiles[x],yp=dataState.profile.profiles[y];$('#timeSliderWrap').classList.toggle('hidden',xp?.type!=='date');let fraction=+$('#timeSlider').value/100,rows=dataState.rows.slice(0,Math.max(2,Math.floor(dataState.rows.length*fraction)));
  if(type==='scatter'&&xp?.type==='numeric'&&yp?.type==='numeric'){const pairs=rows.map(r=>[toNum(r[x]),toNum(r[y])]).filter(a=>a.every(Number.isFinite));drawScatter(canvas,pairs.map(a=>a[0]),pairs.map(a=>a[1]),{xLabel:x,yLabel:y})}
  else if(type==='line'){const vals=rows.map(r=>toNum(r[y])).filter(Number.isFinite);drawLineChart(canvas,vals,{labels:rows.map(r=>String(r[x]).slice(0,10)),color:'cyan'})}
  else if(type==='hist'){const vals=rows.map(r=>toNum(r[y])).filter(Number.isFinite),lo=Math.min(...vals),hi=Math.max(...vals),bins=12,width=(hi-lo||1)/bins,counts=Array(bins).fill(0);vals.forEach(v=>counts[Math.min(bins-1,Math.floor((v-lo)/width))]++);drawBarChart(canvas,counts.map((_,i)=>round(lo+i*width,1)),counts,{color:'purple'})}
  else {const ag=categoryAggregate(x,y);drawBarChart(canvas,ag.map(a=>a[0]),ag.map(a=>a[1]),{color:'gold'})}}
$('#renderChart').onclick=renderMainChart;$('#timeSlider').oninput=e=>{$('#timeSliderOut').textContent=e.target.value+'%';renderMainChart()};
function renderCorrelation(){if(!dataState.profile)return;const canvas=$('#corrCanvas'),s=setupCanvas(canvas);if(!s)return;const {ctx,w,h}=s,c=paletteColors(),cols=dataState.profile.numeric.slice(0,8),n=cols.length;ctx.clearRect(0,0,w,h);if(n<2){ctx.fillStyle=c.muted;ctx.fillText('Need at least two numeric columns.',20,40);return}const pad=90,size=Math.min((w-pad-12)/n,(h-pad-12)/n);ctx.font='9px sans-serif';cols.forEach((col,i)=>{ctx.save();ctx.translate(pad+i*size+size*.45,pad-9);ctx.rotate(-.55);ctx.fillStyle=c.muted;ctx.textAlign='right';ctx.fillText(col.slice(0,14),0,0);ctx.restore();ctx.textAlign='right';ctx.fillText(col.slice(0,13),pad-8,pad+i*size+size*.6)});for(let i=0;i<n;i++)for(let j=0;j<n;j++){const r=i===j?1:pearson(dataState.profile.profiles[cols[i]].values,dataState.profile.profiles[cols[j]].values),alpha=.15+Math.abs(r)*.75;ctx.fillStyle=r>=0?`rgba(102,229,255,${alpha})`:`rgba(255,125,141,${alpha})`;ctx.fillRect(pad+j*size,pad+i*size,size-2,size-2);ctx.fillStyle=Math.abs(r)>.55?'#071019':c.text;ctx.textAlign='center';ctx.fillText(r.toFixed(2),pad+j*size+size/2,pad+i*size+size*.6)}}
$('#downloadChart').onclick=()=>{const a=document.createElement('a');a.download='atlasiq-visualization.png';a.href=$('#mainChart').toDataURL('image/png');a.click()};

// ---------- Lightweight AutoML ----------
function buildDataset(target){const p=dataState.profile,tp=p.profiles[target],featureNames=p.numeric.filter(c=>c!==target),numericTarget=tp.type==='numeric';if(!featureNames.length)throw new Error('At least one numeric feature is required.');const rows=[];for(const r of dataState.rows){const y=numericTarget?toNum(r[target]):String(r[target]??'').trim();if((numericTarget&&!Number.isFinite(y))||(!numericTarget&&!y))continue;rows.push({x:featureNames.map(f=>toNum(r[f])),y})}const means=featureNames.map((_,j)=>avg(rows.map(o=>o.x[j]).filter(Number.isFinite)));rows.forEach(o=>o.x=o.x.map((v,j)=>Number.isFinite(v)?v:means[j]));const train=rows.filter((_,i)=>i%5!==0),test=rows.filter((_,i)=>i%5===0);return{train,test,featureNames,numericTarget}}
function standardizer(rows){const d=rows[0].x.length,means=Array(d).fill(0).map((_,j)=>avg(rows.map(r=>r.x[j]))),stds=Array(d).fill(0).map((_,j)=>Math.sqrt(avg(rows.map(r=>(r.x[j]-means[j])**2)))||1);return{x:x=>x.map((v,j)=>(v-means[j])/stds[j]),means,stds}}
function r2Score(y,p){const m=avg(y),ss=sum(y.map(v=>(v-m)**2));return ss?1-sum(y.map((v,i)=>(v-p[i])**2))/ss:0}
function accuracy(y,p){return avg(y.map((v,i)=>v===p[i]?1:0))}
function trainLinear(train,lambda1=0,lambda2=0){const st=standardizer(train),X=train.map(r=>[1,...st.x(r.x)]),y=train.map(r=>r.y),d=X[0].length,w=Array(d).fill(0),lr=.028;for(let it=0;it<1400;it++){const g=Array(d).fill(0);for(let i=0;i<X.length;i++){const err=sum(X[i].map((v,j)=>v*w[j]))-y[i];for(let j=0;j<d;j++)g[j]+=err*X[i][j]}for(let j=0;j<d;j++){g[j]/=X.length;if(j){g[j]+=lambda2*w[j]+lambda1*Math.sign(w[j])}w[j]-=lr*g[j]}}return{x:(x)=>sum([1,...st.x(x)].map((v,j)=>v*w[j])),weights:w.slice(1).map((v,j)=>v/st.stds[j])}}
function distance(a,b){return Math.sqrt(sum(a.map((v,i)=>(v-b[i])**2)))}
function knnPredict(train,x,k=5,numeric=true){const st=standardizer(train),tx=st.x(x),sorted=train.map(r=>({d:distance(st.x(r.x),tx),y:r.y})).sort((a,b)=>a.d-b.d).slice(0,k);if(numeric)return avg(sorted.map(o=>o.y));const counts={};sorted.forEach(o=>counts[o.y]=(counts[o.y]||0)+1);return Object.entries(counts).sort((a,b)=>b[1]-a[1])[0][0]}
function regressionStump(train){let best={err:Infinity,j:0,t:0,left:0,right:0};for(let j=0;j<train[0].x.length;j++){const vals=train.map(r=>r.x[j]).sort((a,b)=>a-b);for(let q=1;q<8;q++){const t=quantile(vals,q/8),l=train.filter(r=>r.x[j]<=t),rr=train.filter(r=>r.x[j]>t);if(!l.length||!rr.length)continue;const lm=avg(l.map(r=>r.y)),rm=avg(rr.map(r=>r.y)),err=sum(l.map(r=>(r.y-lm)**2))+sum(rr.map(r=>(r.y-rm)**2));if(err<best.err)best={err,j,t,left:lm,right:rm}}}return{x:(x)=>x[best.j]<=best.t?best.left:best.right,feature:best.j}}
function classStump(train){let best={acc:-1,j:0,t:0,left:'',right:''};const mode=a=>Object.entries(a.reduce((o,v)=>(o[v]=(o[v]||0)+1,o),{})).sort((a,b)=>b[1]-a[1])[0]?.[0];for(let j=0;j<train[0].x.length;j++){const vals=train.map(r=>r.x[j]).sort((a,b)=>a-b);for(let q=1;q<8;q++){const t=quantile(vals,q/8),l=train.filter(r=>r.x[j]<=t),rr=train.filter(r=>r.x[j]>t);if(!l.length||!rr.length)continue;const lm=mode(l.map(r=>r.y)),rm=mode(rr.map(r=>r.y)),acc=accuracy(train.map(r=>r.y),train.map(r=>r.x[j]<=t?lm:rm));if(acc>best.acc)best={acc,j,t,left:lm,right:rm}}}return{x:(x)=>x[best.j]<=best.t?best.left:best.right,feature:best.j}}
function gaussianNB(train){const classes=[...new Set(train.map(r=>r.y))],d=train[0].x.length,stats={};classes.forEach(k=>{const rows=train.filter(r=>r.y===k);stats[k]={prior:rows.length/train.length,mean:Array(d).fill(0).map((_,j)=>avg(rows.map(r=>r.x[j]))),variance:Array(d).fill(0).map((_,j)=>avg(rows.map(r=>(r.x[j]-avg(rows.map(q=>q.x[j])))**2))+.0001)}});return x=>classes.map(k=>{const s=stats[k];let log=Math.log(s.prior);for(let j=0;j<d;j++)log+=-.5*Math.log(2*Math.PI*s.variance[j])-((x[j]-s.mean[j])**2)/(2*s.variance[j]);return[k,log]}).sort((a,b)=>b[1]-a[1])[0][0]}
function featureInfluence(ds,target){const t=dataState.profile.profiles[target];if(ds.numericTarget)return ds.featureNames.map(f=>[f,Math.abs(pearson(dataState.profile.profiles[f].values,t.values))]).sort((a,b)=>b[1]-a[1]);const classes=[...new Set(dataState.rows.map(r=>String(r[target]??'')).filter(Boolean))];return ds.featureNames.map(f=>{const vals=classes.map(k=>avg(dataState.rows.filter(r=>String(r[target])===k).map(r=>toNum(r[f])).filter(Number.isFinite))),overall=avg(dataState.rows.map(r=>toNum(r[f])).filter(Number.isFinite)),v=avg(vals.map(x=>(x-overall)**2));return[f,v]}).sort((a,b)=>b[1]-a[1]).map((x,_,a)=>[x[0],x[1]/(a[0]?.[1]||1)])}
function runAutoML(){if(!dataState.profile)return toast('Load a dataset first');const target=$('#targetColumn').value;try{const ds=buildDataset(target);if(ds.train.length<10||ds.test.length<3)throw new Error('Not enough complete rows for a holdout experiment.');let models=[];if(ds.numericTarget){const mean=avg(ds.train.map(r=>r.y)),lin=trainLinear(ds.train),elastic=trainLinear(ds.train,.002,.015),stump=regressionStump(ds.train);models=[['Mean Baseline',()=>mean],['Linear Regression',lin.x],['Elastic Net Approx.',elastic.x],['k-NN Regression',x=>knnPredict(ds.train,x,Math.min(7,ds.train.length),true)],['Decision Stump',stump.x]].map(([name,fn])=>{const pred=ds.test.map(r=>fn(r.x)),score=r2Score(ds.test.map(r=>r.y),pred);return{name,score,pred}})}else{const counts={};ds.train.forEach(r=>counts[r.y]=(counts[r.y]||0)+1);const majority=Object.entries(counts).sort((a,b)=>b[1]-a[1])[0][0],nb=gaussianNB(ds.train),stump=classStump(ds.train);models=[['Majority Baseline',()=>majority],['k-NN Classifier',x=>knnPredict(ds.train,x,Math.min(7,ds.train.length),false)],['Gaussian Naive Bayes',nb],['Decision Stump',stump.x]].map(([name,fn])=>{const pred=ds.test.map(r=>fn(r.x)),score=accuracy(ds.test.map(r=>r.y),pred);return{name,score,pred}})}models.sort((a,b)=>b.score-a.score);const influence=featureInfluence(ds,target);dataState.model={target,ds,models,influence};renderModelResults()}catch(e){toast(e.message)}}
function renderModelResults(){const m=dataState.model,w=m.models[0],metric=m.ds.numericTarget?'R²':'accuracy';$('#modelEmpty').classList.add('hidden');$('#modelResults').classList.remove('hidden');$('#winningModel').textContent=w.name;$('#winningScore').textContent=(w.score*100).toFixed(1)+'%';$('#winningMetric').textContent=metric;$('#winningExplanation').textContent=`Selected from ${m.models.length} local models using a deterministic holdout set. ${w.name} produced the strongest ${metric} on unseen rows.`;$('#modelGrid').innerHTML=m.models.map((x,i)=>`<article class="model-card ${i===0?'winner':''}"><span>${i===0?'BEST HOLDOUT RESULT':'CANDIDATE'}</span><b>${escapeHTML(x.name)}</b><strong>${(x.score*100).toFixed(1)}%</strong><small>${metric}</small></article>`).join('');const max=m.influence[0]?.[1]||1;$('#featureImportance').innerHTML=m.influence.slice(0,7).map(([n,v])=>`<div class="factor-row"><span>${escapeHTML(n)}</span><i><b style="--value:${clamp(v/max*100,2,100)}%"></b></i><em>${Math.round(v/max*100)}</em></div>`).join('');const top=m.influence[0];$('#modelWhy').textContent=`${w.name} won because it generalized best on the reserved 20% holdout set. ${top?`${top[0]} is the strongest measured driver under the current influence method. `:''}A production version should add cross-validation, leakage checks, fairness analysis, and domain review before deployment.`}
$('#runAutoML').onclick=runAutoML;
const methodModal=$('#methodModal');function closeMethodModal(){methodModal.classList.remove('open');methodModal.setAttribute('aria-hidden','true')}$('#showModelDetails').onclick=()=>{methodModal.classList.add('open');methodModal.setAttribute('aria-hidden','false')};methodModal.querySelector('.modal-backdrop').onclick=closeMethodModal;methodModal.querySelector('.modal-close').onclick=closeMethodModal;

// ---------- Dataset decision simulator ----------
$('#simAdjustment').oninput=e=>$('#simAdjustmentOut').textContent=(+e.target.value>0?'+':'')+e.target.value+'%';
function runDataSimulation(){if(!dataState.profile)return toast('Load a dataset first');const target=$('#simTarget').value,feature=$('#simFeature').value;if(target===feature)return toast('Choose different driver and outcome columns');const pairs=cleanPairs(feature,target);if(pairs.length<5)return toast('Not enough complete numeric pairs');const xs=pairs.map(a=>a[0]),ys=pairs.map(a=>a[1]),xm=avg(xs),ym=avg(ys),cov=avg(xs.map((x,i)=>(x-xm)*(ys[i]-ym))),variance=avg(xs.map(x=>(x-xm)**2)),slope=variance?cov/variance:0,adj=+$('#simAdjustment').value/100,newX=xm*(1+adj),pred=ym+slope*(newX-xm),r=pearson(xs,ys);dataState.simulation={target,feature,xm,ym,pred,adj,r,slope};$('#baselineOutcome').textContent=formatNumber(ym);$('#simulatedOutcome').textContent=formatNumber(pred);$('#simulationNarrative').innerHTML=`<span class="alert-dot"></span><p>A <b>${adj>=0?'+':''}${round(adj*100,0)}%</b> change in <b>${escapeHTML(feature)}</b> moves the locally estimated average <b>${escapeHTML(target)}</b> from ${formatNumber(ym)} to ${formatNumber(pred)}. The linear relationship is r=${round(r,2)}. This is a sensitivity estimate, not causal proof.</p>`;drawSimulationChart()}
function drawSimulationChart(){const c=$('#simulationChart');if(!dataState.simulation){const s=setupCanvas(c);if(s){s.ctx.clearRect(0,0,s.w,s.h);s.ctx.fillStyle=paletteColors().muted;s.ctx.fillText('Run a simulation to visualize the counterfactual.',25,40)}return}const q=dataState.simulation,vals=Array.from({length:21},(_,i)=>{const pct=-.5+i*.05;return q.ym+q.slope*(q.xm*(1+pct)-q.xm)});drawLineChart(c,vals,{labels:vals.map((_,i)=>(-50+i*5)+'%'),color:'purple',highlight:Math.round((q.adj+.5)/.05)})}
$('#runDataSimulation').onclick=runDataSimulation;

// ---------- Local conversational analyst ----------
function renderProfileChatReset(){$('#chatMessages').innerHTML='<div class="message ai">Dataset loaded. Ask me about quality, missing values, outliers, correlations, trends, modeling, or preprocessing.</div>'}
function analystAnswer(q){if(!dataState.profile)return'Load a dataset first so I have evidence to analyze.';const s=q.toLowerCase(),p=dataState.profile,top=p.correlations[0];if(/stand out|summary|overview/.test(s))return generateSummary();if(/missing/.test(s)){const cols=p.columns.filter(c=>p.profiles[c].missing).sort((a,b)=>p.profiles[b].missing-p.profiles[a].missing);return cols.length?`Missing values appear in ${cols.map(c=>`${c} (${p.profiles[c].missing})`).join(', ')}. Investigate whether the gaps are random before imputing.`:'No missing values were detected.'}if(/outlier|unusual|anomal/.test(s)){const cols=p.numeric.filter(c=>p.profiles[c].outliers).sort((a,b)=>p.profiles[b].outliers-p.profiles[a].outliers);return cols.length?`IQR screening flagged ${p.totalOutliers} potential outliers. The most affected columns are ${cols.slice(0,4).map(c=>`${c} (${p.profiles[c].outliers})`).join(', ')}. Validate them rather than deleting automatically.`:'IQR screening did not flag numeric outliers.'}if(/correl|relationship|matter|important|driver/.test(s))return top?`The strongest measured numeric relationship is ${top.a} and ${top.b}, with r=${round(top.r,2)}. Correlation does not establish causation, so test alternative explanations and possible leakage.`:'There are not enough numeric columns for correlation analysis.';if(/preprocess|clean/.test(s))return`Recommended plan: handle ${round(p.missingPct,1)}% missing cells using domain-aware imputation, inspect ${p.totalOutliers} outlier flags, standardize numeric features for distance-based models, encode categorical features, and separate preprocessing fit between train and test data.`;if(/model|automl|predict/.test(s)){if(dataState.model)return`${dataState.model.models[0].name} currently leads with ${(dataState.model.models[0].score*100).toFixed(1)}% ${dataState.model.ds.numericTarget?'R²':'accuracy'}. Treat this as an educational holdout result and add cross-validation before making a production claim.`;return'Open AutoML, choose a target, and run the model arena. I will then explain the winner and its strongest feature signals.'}if(/trend|over time|increase|decrease/.test(s)){const date=p.columns.find(c=>p.profiles[c].type==='date'),num=p.numeric[0];if(date&&num){const vals=dataState.rows.map(r=>toNum(r[num])).filter(Number.isFinite),half=Math.floor(vals.length/2),change=(avg(vals.slice(half))-avg(vals.slice(0,half)))/(Math.abs(avg(vals.slice(0,half)))||1)*100;return`${num} changes by approximately ${round(change,1)}% between the first and second halves of the dataset. Use the Visuals time window to inspect whether the shift is gradual or concentrated.`}return'No date-like column was detected. Choose a meaningful order column in Visuals to inspect progression.'}return`I can answer this dataset reliably when the question references quality, missing values, outliers, relationships, trends, preprocessing, or the current model. Try “What stands out?” or “Which variables matter most?”`}
function addChat(role,text){const div=document.createElement('div');div.className='message '+role;div.textContent=text;$('#chatMessages').appendChild(div);$('#chatMessages').scrollTop=$('#chatMessages').scrollHeight}
$('#chatForm').onsubmit=e=>{e.preventDefault();const q=$('#chatInput').value.trim();if(!q)return;addChat('user',q);$('#chatInput').value='';setTimeout(()=>addChat('ai',analystAnswer(q)),180)};$$('.suggestion-chips button').forEach(b=>b.onclick=()=>{addChat('user',b.textContent);setTimeout(()=>addChat('ai',analystAnswer(b.textContent)),160)});
$('#speakSummary').onclick=()=>{if(!('speechSynthesis'in window))return toast('Speech is not supported in this browser');speechSynthesis.cancel();speechSynthesis.speak(new SpeechSynthesisUtterance($('#aiSummaryText').textContent))};

$('#exportReport').onclick=()=>{if(!dataState.profile)return toast('Load a dataset first');const report={product:'AtlasIQ Studio',generated_at:new Date().toISOString(),dataset:dataState.name,domain:dataState.domain,profile:{rows:dataState.profile.rows,columns:dataState.profile.columns,quality:dataState.profile.quality,missing_percent:round(dataState.profile.missingPct,2),outlier_flags:dataState.profile.totalOutliers,strongest_correlations:dataState.profile.correlations.slice(0,10)},model:dataState.model?{target:dataState.model.target,winner:dataState.model.models[0].name,score:dataState.model.models[0].score,feature_influence:dataState.model.influence}:null,simulation:dataState.simulation,summary:generateSummary(),disclaimer:'Educational browser-native analysis. Validate results before real-world decisions.'};downloadFile('atlasiq-analysis-report.json',JSON.stringify(report,null,2))};

