const proofEdges=[['Niveditha','Python'],['Niveditha','Statistics'],['Niveditha','Java'],['Niveditha','Product Design'],['Niveditha','Communication'],['Niveditha','Leadership'],['Niveditha','AtlasIQ'],['Python','AtlasIQ'],['Statistics','AtlasIQ'],['Product Design','AtlasIQ'],['Python','Data Cleaning'],['Communication','Teaching'],['Leadership','Teaching'],['Data Cleaning','AtlasIQ']];
let selectedProof='AtlasIQ';
function drawProofGraph(){const canvas=$('#proofCanvas'),s=setupCanvas(canvas);if(!s)return;const {ctx,w,h}=s,c=paletteColors(),pos={};ctx.clearRect(0,0,w,h);proofNodes.forEach(n=>pos[n.id]={x:n.x*w,y:n.y*h});proofEdges.forEach(([a,b])=>{ctx.strokeStyle='rgba(245,207,98,.18)';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(pos[a].x,pos[a].y);ctx.lineTo(pos[b].x,pos[b].y);ctx.stroke()});proofNodes.forEach(n=>{const p=pos[n.id],sel=n.id===selectedProof,r=n.type==='root'?42:n.type==='project'?35:27;ctx.fillStyle=sel?c.gold:n.type==='project'?c.purple:n.type==='experience'?c.green:c.panel;ctx.strokeStyle=sel?'#fff4c0':n.type==='skill'?c.cyan:c.gold;ctx.lineWidth=sel?3:1.5;ctx.beginPath();ctx.arc(p.x,p.y,r,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle=sel||n.type==='project'?'#111520':c.text;ctx.textAlign='center';ctx.font=`${sel?'700':'600'} ${n.id.length>12?'9':'11'}px sans-serif`;const words=n.id.split(' ');if(words.length>1){ctx.fillText(words[0],p.x,p.y-2);ctx.fillText(words.slice(1).join(' '),p.x,p.y+11)}else ctx.fillText(n.id,p.x,p.y+4)});canvas.onclick=e=>{const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)*(canvas.width/(devicePixelRatio||1))/r.width,y=(e.clientY-r.top)*(canvas.height/(devicePixelRatio||1))/r.height;const hit=proofNodes.find(n=>Math.hypot(x-n.x*r.width,y-n.y*(canvas.height/(devicePixelRatio||1)))<44);if(hit){selectedProof=hit.id;renderProofEvidence();drawProofGraph()}}}
function renderProofEvidence(){const n=proofNodes.find(x=>x.id===selectedProof);$('#proofDescription').textContent=`${n.id} is backed by ${n.evidence.length} concrete evidence signal${n.evidence.length>1?'s':''}.`;$('#proofEvidence').innerHTML=n.evidence.map((e,i)=>`<div class="evidence-card"><span>EVIDENCE ${String(i+1).padStart(2,'0')}</span><b>${escapeHTML(e)}</b><small>${n.type==='skill'?'Skill proof':'Experience artifact'}</small></div>`).join('')}
$('#exportProof').onclick=()=>downloadFile('niveditha-proofgraph.json',JSON.stringify({founder:'Niveditha Mallojhala',nodes:proofNodes,edges:proofEdges},null,2));renderProofEvidence();setTimeout(drawProofGraph,80);

// ---------- About, exports, startup ----------
const aboutBio=`I'm Niveditha Mallojhala, a Data Science student at Purdue University interested in the full path from raw information to a decision someone can confidently act on. I combine statistics, programming, data cleaning, visualization, communication, and product design to build understandable, evidence-driven tools. AtlasIQ is a privacy-first decision intelligence platform that models student choices and turns raw datasets into explainable analysis.`;
$('#copyAbout').onclick=()=>copyText(aboutBio);

// initialize a useful demo while preserving the upload-first experience
setTimeout(()=>{drawAllCanvases();},100);
addEventListener('resize',()=>{clearTimeout(window.__atlasResize);window.__atlasResize=setTimeout(drawAllCanvases,100)});

